import{_ as r}from"./chunks/09-login.Cp0oUy7l.js";import{_ as e,a as o,b as a}from"./chunks/13b-mobile-drawer.BiU5fk85.js";import{_ as i}from"./chunks/11-settings.B_GZgwvL.js";import{_ as s}from"./chunks/11b-settings-add-root.Dcjj_7UM.js";import{_ as d}from"./chunks/01-files-browse.Dr_PlV-Q.js";import{_ as n}from"./chunks/01c-files-reports.DZ25K_9T.js";import{_ as l}from"./chunks/12-audit.CWIaVMMc.js";import{_ as p}from"./chunks/07-health.CsoSZ-cX.js";import{_ as g,o as c,c as f,a0 as h}from"./chunks/framework.DVzt4Sxt.js";const C=JSON.parse('{"title":"首次登录与添加目录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-login.md","filePath":"guide/first-login.md","lastUpdated":1791394961000}'),m={name:"guide/first-login.md"};function _(u,t,b,x,A,S){return c(),f("div",null,[...t[0]||(t[0]=[h('<h1 id="首次登录与添加目录" tabindex="-1">首次登录与添加目录 <a class="header-anchor" href="#首次登录与添加目录" aria-label="Permalink to &quot;首次登录与添加目录&quot;">​</a></h1><p>跑通 Hub 与 Agent 之后，在浏览器里完成：登录（含 PoW）→ 选机器 → Add Root → 开始浏览。</p><h2 id="_1-打开登录页" tabindex="-1">1. 打开登录页 <a class="header-anchor" href="#_1-打开登录页" aria-label="Permalink to &quot;1. 打开登录页&quot;">​</a></h2><p>访问 Hub URL。登录页包含：</p><ul><li>Username / Password</li><li><strong>Verification（PoW）</strong>：后台求解 challenge，显示 Solving… → <strong>Ready</strong></li><li>Keep me signed in 30 days（可选）</li><li><strong>Continue</strong></li></ul><p><img src="'+r+'" alt="Sign in：PoW Ready"></p><p><img src="'+e+'" alt="已填写凭据"></p><p>生产账号使用 <code>--init-config</code> 时创建的用户名 / 密码。开发模式默认 <code>admin</code> / <code>dev-password</code>。</p><p>若 Verification 失败或限流，点刷新图标重新拉取 challenge，稍后再试。</p><h2 id="_2-选择-agent" tabindex="-1">2. 选择 Agent <a class="header-anchor" href="#_2-选择-agent" aria-label="Permalink to &quot;2. 选择 Agent&quot;">​</a></h2><p>登录成功后，若尚未选中机器，主区会提示 <strong>Select an agent</strong>。在侧栏 <strong>Agents</strong> 点击目标机器（显示 Online、延迟、roots 数）。</p><p>选中后，侧栏出现 <strong>Workspace</strong> 导航：Files、Explorer、Collections、Transfer、Terminal、Search、Settings、System；以及 <strong>Hub → Audit</strong>。</p><h2 id="_3-settings-→-add-root" tabindex="-1">3. Settings → Add Root <a class="header-anchor" href="#_3-settings-→-add-root" aria-label="Permalink to &quot;3. Settings → Add Root&quot;">​</a></h2><p>打开 <strong>Settings</strong>：</p><ol><li>确认 Connection 卡片：Online、Round-trip、Enabled roots。</li><li>在 <strong>Workspace roots</strong> 下的 <strong>Add root</strong> 填写： <ul><li><strong>NAME</strong>：侧栏 / 地址栏里显示的短名（如 <code>demo</code>、<code>projects</code>）</li><li><strong>PATH ON AGENT</strong>：Agent 本机上的绝对路径，或 <code>~/…</code></li></ul></li><li>点 <strong>Add root</strong>。过宽路径（如 <code>/</code>、家目录根）会弹出确认，需明确同意。</li></ol><p><img src="'+i+'" alt="Settings 总览"></p><p><img src="'+s+'" alt="Add root 表单"></p><p>无效路径会被拒绝，<strong>不会</strong>破坏已有配置。根目录、钉选、合集存在 Agent 状态里，随身份持久化。</p><h2 id="_4-进入-files-浏览" tabindex="-1">4. 进入 Files 浏览 <a class="header-anchor" href="#_4-进入-files-浏览" aria-label="Permalink to &quot;4. 进入 Files 浏览&quot;">​</a></h2><p>回到 <strong>Files</strong>，用根下拉框切换 root，点进目录，点击文件即可右侧预览。</p><p><img src="'+d+'" alt="Files 根目录列表"></p><p><img src="'+n+'" alt="reports 目录（长文件名）"></p><h2 id="侧栏视图一览" tabindex="-1">侧栏视图一览 <a class="header-anchor" href="#侧栏视图一览" aria-label="Permalink to &quot;侧栏视图一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>视图</th><th>作用</th><th>文档</th></tr></thead><tbody><tr><td>Files</td><td>面包屑 + 列表浏览，多标签预览</td><td><a href="/filebox/features/browse">浏览文件</a></td></tr><tr><td>Explorer</td><td>树形展开式浏览</td><td><a href="/filebox/features/explorer">Explorer</a></td></tr><tr><td>Search</td><td>工作区文件名 / 内容搜索（桌面浮窗 / 手机底部 sheet）</td><td><a href="/filebox/features/search">搜索</a></td></tr><tr><td>Collections</td><td>跨目录的虚拟文件合集</td><td><a href="/filebox/features/collections">合集</a></td></tr><tr><td>Transfer</td><td>唯一可写的临时上传目录</td><td><a href="/filebox/features/transfer">Transfer</a></td></tr><tr><td>Terminal</td><td>可选，TOTP 守护的远程 shell</td><td><a href="/filebox/features/terminal">Terminal</a></td></tr><tr><td>Settings</td><td>管理根目录、Office 预览开关</td><td>本文</td></tr><tr><td>System</td><td>CPU / 内存 / 进程</td><td><a href="/filebox/features/stats">系统监控</a></td></tr><tr><td>Audit</td><td>登录审计（不依赖选中 Agent）</td><td><a href="/filebox/ops/hub">Hub 运维</a></td></tr><tr><td>版本号</td><td>点击打开 About / Diagnostics</td><td>—</td></tr></tbody></table><p><img src="'+l+'" alt="Audit"></p><p><img src="'+p+'" alt="About / Diagnostics"></p><h2 id="手机" tabindex="-1">手机 <a class="header-anchor" href="#手机" aria-label="Permalink to &quot;手机&quot;">​</a></h2><p>视口宽度小于约 768px 时使用抽屉侧栏；列表与预览全屏切换。顶部有菜单与 Search 入口。</p><p><img src="'+o+'" alt="手机 Files"></p><p><img src="'+a+'" alt="手机侧栏抽屉"></p><p>常见问题见 <a href="/filebox/ops/faq">FAQ</a>。</p>',31)])])}const N=g(m,[["render",_]]);export{C as __pageData,N as default};
